"""三命通会 993 条跨本候选坐标重锚登记册（TJ-018 重锚批，纯数据
登记，零计算逻辑；不是 canonical 晋级批——候选状态语义逐字未动，
未应用任何候选到快照/canonical，TJ-018.3 晋级决策不在本批）。

背景：密封侧 ``sanming_ocr_candidates.json`` 993 条跨本候选
（historical_only_hold 775、variant_preserve 47、
confirmed_applied 159、reading_disagreement_hold 12）的
``offset_basis`` 自述为「raw → 86 PUA 映射 → ocr-001..444 应用
后」的字符偏移，对钉定快照（``sanming_tonghui.txt``，SHA256
00e2a7db…、461,157 字）直接使用实测 **0/993 对位**（018-H 路线
备忘在案）：748 条 context 在快照他处可寻、245 条只存在于后续
阶段文本。终局化（TJ-018.3）前必须重锚，本批完成重锚与逐条
核验登记。

实测口径澄清（本批机上实测）：``baseline_character_offset``
指向**候选位点本身**（old 串起点，993/993 在基线文本中逐字
命中），不是 context 起点；context 是位点前后 28–59 字的窗口，
位点在 context 内偏移逐条登记 ``site_in_context``（实测
3–25，众数段 18–22）。

方法（机上实测，脚本口径与复算方法随 PR 正文在案）：以带
origin 位点图的忠实复放重建基线文本——PUA 阶段 86 映射全
等长（统一映射 85 条 1→1、U+E7E8 语境 4 规则等长替换），位置
恒等；文本阶段按 ``apply_sanming_text_collation.py`` 全规则
（锚串恰 1 次、目标串预存校验、allow_existing_target 豁免）
以文件序应用 ocr-001..444（仅 ocr-017 变长）。复放产出与仓库
脚本实际运行输出**逐字等值**（461,156 字、SHA256 db8618c9…）。
逐条候选：位点与 context 在基线文本中核验（context 出现位置
按「含位点且位点处为 old」唯一钉住，993/993 唯一），再经
origin 图逆映射回快照坐标。

锚定分类（定义先行、计数如实）：
- 位点（site）：``anchored_direct`` 942（位点字符未被文本订正
  改写，快照位点精确）；``anchored_within_single_edit`` 51
  （位点字符是某条基线订正的产物，其快照前像 = 该订正消费的
  快照区间整段，位点在 old 串内的精确子位不可定，整段登记）；
  **不可锚位点 0**。
- context：``anchored_direct`` 900（不含文本订正产物字符；
  其中 168 条含 PUA 派生字、快照前像含 PUA 原字，故逐字检索
  快照不可寻但锚精确）；``anchored_through_edits`` 17（完整
  覆盖 1+ 条订正的替换域，快照前像区间正向应用所覆盖订正
  恰得 context，往返校验 17/17）；``unanchorable_crosses_
  boundary`` 76（与订正替换域部分交叠 52、或整体位于一条长
  订正替换域之内 24——替换域内字符无逐字前像，context 级
  快照区间不可定；其位点本身仍全部可锚）。
- 159 条 confirmed_applied 的 correction_id 恰为
  ocr-445..ocr-603（基线未应用段），与 603 订正集逐一对应，
  在册登记其对应关系；本批不核销、不应用。

处置口径：本登记册只确立坐标对应与核验事实。TJ-018.3 终局化
还缺的要件（PUA/文本两阶段的正式应用批与应用报告、残余防
769 处处置路线、12 条 reading_disagreement_hold 见证互校、
76 条 context 不可锚候选的证据面处置、manifest 在案
unresolved_text_gaps 2 处）逐项评估见
``docs/product/TJ018_REANCHOR_ASSESSMENT.md``。整书仍
quarantine_only、canonical_ready=false 不变；候选 JSON、快照、
订正/PUA JSON 逐字未动。
"""

